-- Read-only verification. Select target database first.
SET NAMES utf8mb4;
SELECT p.project_code,p.project_name,v.version_code,v.version_name,v.lifecycle_status,v.data_status,(SELECT COUNT(*) FROM energy_dataset_file f WHERE f.version_id=v.version_id) AS frozen_files FROM energy_project p JOIN energy_project_version v ON v.project_id=p.project_id WHERE p.project_code=CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4) ORDER BY v.version_code;
SELECT version_code,version_name,status,data_status,JSON_CONTAINS_PATH(files_json,'one','$."locomotive_curves.json"') AS has_curves FROM single_version WHERE project_code=CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4);
SELECT dept_id,project_code,enabled FROM energy_dept_project WHERE project_code=CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4);
SELECT dept_id,project_code,enabled FROM single_dept_project WHERE project_code=CONVERT(0x616c676f726974686d5f64656d6f5f32303236313131335f616c6c USING utf8mb4);
SELECT 'planning_sites' AS item,COUNT(*) AS rows_found FROM energy_storage_candidate_site WHERE version_id=CONVERT(0x37666665613230662d306631342d353033612d383133392d623264663230356434633530 USING utf8mb4) UNION ALL SELECT 'planning_technologies',COUNT(*) FROM energy_storage_technology WHERE version_id=CONVERT(0x37666665613230662d306631342d353033612d383133392d623264663230356434633530 USING utf8mb4) UNION ALL SELECT 'planning_scenarios',COUNT(*) FROM energy_storage_planning_scenario WHERE version_id=CONVERT(0x37666665613230662d306631342d353033612d383133392d623264663230356434633530 USING utf8mb4) UNION ALL SELECT 'planning_policy',COUNT(*) FROM energy_storage_planning_policy WHERE version_id=CONVERT(0x37666665613230662d306631342d353033612d383133392d623264663230356434633530 USING utf8mb4);

-- Frozen traction/brake/resistance values used by eco-driving.
SELECT version_code, JSON_EXTRACT(parameters_json,'$.train.provenance.platform_shared_train.max_traction_kN') AS traction_kN, JSON_EXTRACT(parameters_json,'$.train.provenance.platform_shared_train.max_brake_kN') AS brake_kN, JSON_EXTRACT(parameters_json,'$.train.provenance.platform_shared_train.davis_a') AS davis_a, JSON_EXTRACT(parameters_json,'$.train.provenance.platform_shared_train.davis_b') AS davis_b, JSON_EXTRACT(parameters_json,'$.train.provenance.platform_shared_train.davis_c') AS davis_c FROM single_version WHERE project_code='algorithm_demo_20261113_all';
